 r=subprocess.run(args,cwd=work,env=env,text=True,input=data,capture_output=True,timeout=240);(p/(name+'.log')).write_text(r.stdout+r.stderr);entry={'name':name,'command':args,'exit':r.returncode,'expected_exit':expected_code};results.append(entry);(p/'commitlint-qualification.partial.json').write_text(json.dumps(results,indent=2)+'\n');assert (r.returncode==0)==(expected_code==0),entry;return r
